using System;

namespace Halibut.Exceptions
{
    public class HalibutClientException : Exception
    {
        public HalibutClientException(string message) : base(message) { }
        public ConnectionState ConnectionState { get; set; }
    }

    public class ConnectingRequestCancelledException : HalibutClientException
    {
        public ConnectingRequestCancelledException() : base("connecting cancelled") { }
    }
}

namespace Halibut.Transport
{
    public enum ConnectionState
    {
        Connecting,
        Transferring
    }
}

public static class Sanity
{
    public static bool IsConnecting(Exception ex) =>
        ex is Halibut.Exceptions.ConnectingRequestCancelledException ||
        ex is Halibut.Exceptions.HalibutClientException { ConnectionState: Halibut.Transport.ConnectionState.Connecting };

    public static bool Test()
    {
        if (!IsConnecting(new Halibut.Exceptions.ConnectingRequestCancelledException())) return false;
        var fallback = new Halibut.Exceptions.HalibutClientException("x");
        fallback.ConnectionState = Halibut.Transport.ConnectionState.Connecting;
        if (!IsConnecting(fallback)) return false;
        var transferring = new Halibut.Exceptions.HalibutClientException("x");
        transferring.ConnectionState = Halibut.Transport.ConnectionState.Transferring;
        return !IsConnecting(transferring);
    }
}

