#nullable enable
using System;
using System.Collections.Concurrent;
using System.Collections.Generic;
using System.Linq;

namespace Octopus.Tentacle.Contracts.Legacy
{
    public class ReMappedLegacyTypes
    {
        static readonly string[] LegacyContractTypeNames =
        {
            nameof(CancelScriptCommand),
            nameof(CompleteScriptCommand),
            nameof(IFileTransferService),
            nameof(IScriptService),
            nameof(ScriptFile),
            nameof(ScriptIsolationLevel),
            nameof(ScriptStatusRequest),
            nameof(ScriptStatusResponse),
            nameof(ScriptTicket),
            nameof(ScriptType),
            nameof(StartScriptCommand),
            nameof(UploadResult)
        };

        static readonly ConcurrentDictionary<string, ReMappedLegacyTypes> CacheByNameSpaces =
            new ConcurrentDictionary<string, ReMappedLegacyTypes>(StringComparer.Ordinal);

        readonly HashSet<string> fullNameOfTypesToRemap;

        internal ReMappedLegacyTypes(params string[] nameSpaces)
        {
            var set = new HashSet<string>();

            foreach (var nameSpace in nameSpaces)
            {
                foreach (var typeName in LegacyContractTypeNames)
                {
                    set.Add(nameSpace + "." + typeName);
                }
            }

            fullNameOfTypesToRemap = set;
        }

        internal static ReMappedLegacyTypes GetReMappedLegacyTypes(params string[] nameSpaces)
        {
            var key = string.Join(",", nameSpaces.Distinct().OrderBy(n => n, StringComparer.Ordinal));

            return CacheByNameSpaces.GetOrAdd(key, _ => new ReMappedLegacyTypes(nameSpaces));
        }

        internal bool ShouldRemap(string? fullTypeName)
        {
            if (fullTypeName == null) return false;

            return fullNameOfTypesToRemap.Contains(fullTypeName);
        }
    }
}

