using System;

namespace Newtonsoft.Json.Serialization
{
    public interface ISerializationBinder
    {
        Type BindToType(string? assemblyName, string typeName);
        void BindToName(Type serializedType, out string? assemblyName, out string? typeName);
    }

    public class DefaultSerializationBinder : ISerializationBinder
    {
        public Type BindToType(string? assemblyName, string typeName) => typeof(object);
        public void BindToName(Type serializedType, out string? assemblyName, out string? typeName)
        {
            assemblyName = null;
            typeName = null;
        }
    }
}

namespace Octopus.Tentacle.Contracts
{
    public class CancelScriptCommand { }
    public class CompleteScriptCommand { }
    public interface IFileTransferService { }
    public interface IScriptService { }
    public class ScriptFile { }
    public enum ScriptIsolationLevel { }
    public class ScriptStatusRequest { }
    public class ScriptStatusResponse { }
    public class ScriptTicket { }
    public enum ScriptType { }
    public class StartScriptCommand { }
    public class UploadResult { }
}

using System;
using System.Collections.Generic;
using System.Linq;
using System.Threading.Tasks;
using Octopus.Tentacle.Contracts.Legacy;

class Program
{
    static int failures;

    static void Check(bool condition, string message)
    {
        if (!condition)
        {
            failures++;
            Console.WriteLine("FAIL: " + message);
        }
    }

    static bool OriginalShouldRemap(string? fullTypeName, string[] nameSpaces, string[] typeNames)
    {
        if (fullTypeName == null) return false;
        var set = new HashSet<string>();
        foreach (var ns in nameSpaces)
            foreach (var t in typeNames)
                set.Add(ns + "." + t);
        return set.Contains(fullTypeName);
    }

    static void Main()
    {
        var ns1 = new[] { "Octopus.Shared.Contracts", "Octopus.Tentacle.Contracts" };
        var ns2 = new[] { "Octopus.Shared.Contracts", "Octopus.Tentacle.Contracts" };

        var a = ReMappedLegacyTypes.GetReMappedLegacyTypes(ns1);
        var b = ReMappedLegacyTypes.GetReMappedLegacyTypes(ns2);
        var c = ReMappedLegacyTypes.GetReMappedLegacyTypes("Other.Namespace");

        Check(ReferenceEquals(a, b), "same namespaces should return the same cached instance");
        Check(!ReferenceEquals(a, c), "different namespaces should not share the same instance");

        var typeNames = new[]
        {
            nameof(Octopus.Tentacle.Contracts.CancelScriptCommand),
            nameof(Octopus.Tentacle.Contracts.CompleteScriptCommand),
            nameof(Octopus.Tentacle.Contracts.IFileTransferService),
            nameof(Octopus.Tentacle.Contracts.IScriptService),
            nameof(Octopus.Tentacle.Contracts.ScriptFile),
            nameof(Octopus.Tentacle.Contracts.ScriptIsolationLevel),
            nameof(Octopus.Tentacle.Contracts.ScriptStatusRequest),
            nameof(Octopus.Tentacle.Contracts.ScriptStatusResponse),
            nameof(Octopus.Tentacle.Contracts.ScriptTicket),
            nameof(Octopus.Tentacle.Contracts.ScriptType),
            nameof(Octopus.Tentacle.Contracts.StartScriptCommand),
            nameof(Octopus.Tentacle.Contracts.UploadResult)
        };

        var samples = new string?[]
        {
            null,
            "",
            "Octopus.Shared.Contracts.StartScriptCommand",
            "Octopus.Tentacle.Contracts.StartScriptCommand",
            "Octopus.Shared.Contracts.ScriptTicket",
            "Octopus.Tentacle.Contracts.UploadResult",
            "Octopus.Shared.Contracts.SomeOtherCommand",
            "Some.Random.Type",
            "Octopus.Shared.Contracts.CancelScriptCommand",
            "startscriptcommand",
            "Octopus.Tentacle.Contracts.IFileTransferService"
        };

        foreach (var s in samples)
        {
            var expected = OriginalShouldRemap(s, ns1, typeNames);
            Check(a.ShouldRemap(s) == expected, $"a.ShouldRemap({s}) == {expected}");
            Check(c.ShouldRemap(s) == OriginalShouldRemap(s, new[] { "Other.Namespace" }, typeNames), $"c.ShouldRemap({s})");
        }

        Parallel.For(0, 100000, i =>
        {
            var s = samples[i % samples.Length];
            var expected = OriginalShouldRemap(s, ns1, typeNames);
            if (a.ShouldRemap(s) != expected) throw new Exception("concurrent mismatch: " + s);
            if (c.ShouldRemap(s) != OriginalShouldRemap(s, new[] { "Other.Namespace" }, typeNames)) throw new Exception("concurrent mismatch c: " + s);
        });

        Console.WriteLine(failures == 0 ? "ALL CHECKS PASSED" : failures + " CHECKS FAILED");
        Environment.Exit(failures == 0 ? 0 : 1);
