using System;
using System.Reflection;
using Nuke.Common.Tooling;
using Nuke.Common.Tools.Docker;

static class Program
{
    static void Main()
    {
        try { Run(); }
        catch (Exception e)
        {
            Console.Error.WriteLine("UNHANDLED: " + e.GetType().FullName + " | " + e.Message);
            Console.Error.Flush();
        }
    }

    static void Run()
    {
        var pullTrue = new DockerPullSettings()
            .SetName("image")
            .When(true, x => x.SetPlatform("linux/amd64"));
        var pullFalse = new DockerPullSettings()
            .SetName("image")
            .When(false, x => x.SetPlatform("linux/amd64"));

        var runTrue = new DockerRunSettings()
            .EnableRm().SetImage("image")
            .When(true, x => x.SetPlatform("linux/amd64"));
        var runFalse = new DockerRunSettings()
            .EnableRm().SetImage("image")
            .When(false, x => x.SetPlatform("linux/amd64"));

        Console.WriteLine($"pull/true  Platform = '{PlatformOf(pullTrue)}'");
        Console.WriteLine($"pull/false Platform = '{PlatformOf(pullFalse)}'");
        Console.WriteLine($"run/true   Platform = '{PlatformOf(runTrue)}'");
        Console.WriteLine($"run/false  Platform = '{PlatformOf(runFalse)}'");
    }

    static object PlatformOf(object o)
    {
        var prop = o.GetType().GetProperty("Platform", BindingFlags.Instance | BindingFlags.Public | BindingFlags.NonPublic);
        return prop.GetValue(o);
    }
}

