using System;
using System.Numerics;
using System.Text;

namespace Octopus.Tentacle.Contracts.Builders
{
    public class UniqueScriptTicketBuilder
    {
        const string Alphabet = "0123456789abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ";

        public ScriptTicket Build()
        {
            var guidBytes = Guid.NewGuid().ToByteArray();
            var bytes = new byte[guidBytes.Length + 1];
            guidBytes.CopyTo(bytes, 0);

            return new ScriptTicket(ToBaseN(new BigInteger(bytes), 62));
        }

        static string ToBaseN(BigInteger value, int radix)
        {
            if (value == 0)
                return Alphabet[0].ToString();

            var result = new StringBuilder();
            while (value > 0)
            {
                value = BigInteger.DivRem(value, radix, out var remainder);
                result.Insert(0, Alphabet[(int)remainder]);
            }

            return result.ToString();
        }
    }
}

