namespace Octopus.Tentacle.Tests.Contracts
{
    [TestFixture]
    public class UniqueScriptTicketBuilderFixture
    {
        const int GeneratedTicketsCount = 1000;

        [Test]
        public void GeneratedTicketsShouldBeShorterThanAGuid()
        {
            var generatedTickets = GenerateTickets();

            foreach (var ticket in generatedTickets)
            {
                ticket.TaskId.Length.Should().BeInRange(10, 22);
            }
        }

        [Test]
        public void GeneratedTicketsShouldBeAlphanumericAndSafeForFolderNames()
        {
            var generatedTickets = GenerateTickets();

            foreach (var ticket in generatedTickets)
            {
                ticket.TaskId.Should().NotBeNullOrWhiteSpace();
                ticket.TaskId.All(char.IsLetterOrDigit).Should().BeTrue("script ticket ids are used as folder names and must be alphanumeric");
            }
        }

        [Test]
        public void GeneratedTicketsShouldBeUnique()
        {
            var generatedTickets = GenerateTickets();

            generatedTickets.Select(ticket => ticket.TaskId).Distinct().Count().Should().Be(GeneratedTicketsCount);
        }

        static ScriptTicket[] GenerateTickets()
            => Enumerable.Range(0, GeneratedTicketsCount)
                .Select(_ => new UniqueScriptTicketBuilder().Build())
                .ToArray();
    }
}

