        var cmdV3 = new StartScriptCommandV3AlphaBuilder().WithScriptBody("echo hi").Build();
        if (cmdV3.Isolation != ScriptIsolationLevel.FullIsolation) { Console.WriteLine("FAIL v3 isolation"); return 1; }
