    public class CombiningTentacleServiceDecoratorFactory : ITentacleServiceDecoratorFactory
    {
        readonly List<ITentacleServiceDecoratorFactory> factories;

        public CombiningTentacleServiceDecoratorFactory(params ITentacleServiceDecoratorFactory[] factories)
        {
            this.factories = factories.ToList();
        }

        public IAsyncClientScriptService Decorate(IAsyncClientScriptService scriptService)
        {
            var decoratedService = scriptService;
            for (var i = factories.Count - 1; i >= 0; i--)
            {
                decoratedService = factories[i].Decorate(decoratedService);
            }
            return decoratedService;
        }

