public class TentacleServiceDecoratorBuilder
    {
        readonly Dictionary<Type, List<ProxyDecoratorFactory>> registeredProxyDecorators = new();
        readonly List<Decorator<IAsyncClientScriptService>> scriptServicePerMethodDecorators = new();
        readonly List<Decorator<IAsyncClientScriptServiceV2>> scriptServiceV2PerMethodDecorators = new();
        readonly List<Decorator<IAsyncClientFileTransferService>> fileTransferServicePerMethodDecorators = new();
        readonly List<Decorator<IAsyncClientCapabilitiesServiceV2>> capabilitiesServiceV2PerMethodDecorators = new();

        internal ITentacleServiceDecoratorFactory Build()
            => new CombiningTentacleServiceDecoratorFactory(
                new ProxyTentacleServiceDecoratorFactory(registeredProxyDecorators),
                new PerServiceTentacleServiceDecoratorFactory(
                    scriptServicePerMethodDecorators,
                    scriptServiceV2PerMethodDecorators,
                    fileTransferServicePerMethodDecorators,
                    capabilitiesServiceV2PerMethodDecorators));

        public TentacleServiceDecoratorBuilder DecorateScriptServiceWith(Decorator<IAsyncClientScriptService> decorator)
        {
            scriptServicePerMethodDecorators.Add(decorator);
            return this;
        }

        public TentacleServiceDecoratorBuilder DecorateScriptServiceWith(Action<ScriptServiceDecoratorBuilder> configure)
        {
