            configure(builder);
            return DecorateFileTransferServiceWith(builder.Build());
        }

        public TentacleServiceDecoratorBuilder DecorateCapabilitiesServiceV2With(Decorator<IAsyncClientCapabilitiesServiceV2> decorator)
        {
            capabilitiesServiceV2PerMethodDecorators.Add(decorator);
            return this;
        }

        public TentacleServiceDecoratorBuilder DecorateCapabilitiesServiceV2With(Action<CapabilitiesServiceV2DecoratorBuilder> configure)
        {
            var builder = new CapabilitiesServiceV2DecoratorBuilder();
            configure(builder);
            return DecorateCapabilitiesServiceV2With(builder.Build());
