                .DecorateScriptServiceV2With(builder => builder.DecorateStartScriptWith(async (service, command, proxyRequestOptions) =>
                {
                    callbacks.Add(2);
                    return await service.StartScriptAsync(command, proxyRequestOptions);
                }))
                .DecorateScriptServiceV2With(builder => builder.BeforeStartScript(async (service, command) =>
                {
                    callbacks.Add(3);
                    await Task.CompletedTask;
                }))
                .DecorateScriptServiceV2With<ScriptServiceV2DecoratorBuilder>(new TestScriptServiceV2Decorator((service, command, proxyRequestOptions) => throw new Exception($"unechoed callbacks: {string.Join(",", callbacks)}")));

            var innerService = Substitute.For<IAsyncClientScriptServiceV2>();
            innerService.StartScriptAsync(Arg.Any<StartScriptCommandV2>(), Arg.Any<HalibutProxyRequestOptions>())
                .Returns(new ScriptStatusResponseV2(new ScriptTicket("test"), ProcessState.Complete, 0, new List<ProcessOutput>(), 0));

            var decoratedService = tentacleServiceDecoratorBuilder.Build().Decorate(innerService);

            await decoratedService.StartScriptAsync(
                BuildStartScriptCommand(),
                new HalibutProxyRequestOptions(CancellationToken.None));

            callbacks.Should().Equal(1, 2, 3);
        }

