            var innerService = Substitute.For<IAsyncClientScriptServiceV2>();
            innerService.StartScriptAsync(Arg.Any<StartScriptCommandV2>(), Arg.Any<HalibutProxyRequestOptions>())
                .Returns(new ScriptStatusResponseV2(new ScriptTicket("test"), ProcessState.Complete, 0, new List<ProcessOutput>(), 0));

            var decoratedService = tentacleServiceDecoratorBuilder.Build().Decorate(innerService);

            var act = async () => await decoratedService.StartScriptAsync(
                BuildStartScriptCommand(),
                new HalibutProxyRequestOptions(CancellationToken.None));

            await act.Should().ThrowAsync<Exception>().WithMessage("Boom");

            recordedUsages.For(nameof(IAsyncClientScriptServiceV2.StartScriptAsync)).Started.Should().Be(1);
        }

        static StartScriptCommandV2 BuildStartScriptCommand()
            => new(
                "echo hello",
                ScriptIsolationLevel.NoIsolation,
                TimeSpan.Zero,
                null,
                Array.Empty<string>(),
                "TaskId",
                new ScriptTicket("TicketId"),
                TimeSpan.FromSeconds(5));

        class TestScriptServiceV2Decorator : ScriptServiceV2DecoratorBuilder
        {
            public TestScriptServiceV2Decorator(ScriptServiceV2DecoratorBuilder.StartScriptClientDecorator decorator)
            {
                DecorateStartScriptWith(decorator);
            }
        }
    }
}

