using System;
using System.Collections.Generic;
using System.Threading;
using System.Threading.Tasks;
using Halibut;
using Halibut.ServiceModel;
using Octopus.Tentacle.Client;
using Octopus.Tentacle.Contracts;
using Octopus.Tentacle.Contracts.ClientServices;
using Octopus.Tentacle.Contracts.ScriptServiceV2;
using Octopus.Tentacle.Tests.Integration.Util.Builders.Decorators;

public static class Program
{
    static int failures;

    public static int Main()
    {
        PerServiceDecoratorsAreCalledInTheOrderTheyWereDefined();
        DecorateWithRawDecoratorWorks();
        CombiningTentacleServiceDecoratorFactoryAppliesFirstFactoryOutermost();
        CallThroughDefaultsArePreserved();

        if (failures > 0)
        {
            Console.WriteLine($"FAILED: {failures} assertion(s)");
            return 1;
        }

        Console.WriteLine("ALL PASSED");
        return 0;
    }

    static void PerServiceDecoratorsAreCalledInTheOrderTheyWereDefined()
    {
        var callbacks = new List<int>();

        var rawDecorator = new ScriptServiceV2DecoratorBuilder()
            .BeforeStartScript(() =>
            {
                callbacks.Add(3);
                return Task.CompletedTask;
            })
            .Build();

        var decoratorBuilder = new TentacleServiceDecoratorBuilder()
            .DecorateScriptServiceV2With(builder => builder.BeforeStartScript(() =>
            {
                callbacks.Add(1);
                return Task.CompletedTask;
            }))
            .DecorateScriptServiceV2With(builder => builder.DecorateStartScriptWith(async (service, command, proxyRequestOptions) =>
            {
                callbacks.Add(2);
                return await service.StartScriptAsync(command, proxyRequestOptions);
            }))
            .DecorateScriptServiceV2With(rawDecorator);

        var decoratedService = decoratorBuilder.Build().Decorate(new FakeScriptServiceV2());

        decoratedService.StartScriptAsync(BuildStartScriptCommand(), new HalibutProxyRequestOptions(CancellationToken.None)).GetAwaiter().GetResult();

        Check(callbacks.Count == 3 && callbacks[0] == 1 && callbacks[1] == 2 && callbacks[2] == 3,
            $"PerServiceDecoratorsAreCalledInTheOrderTheyWereDefined -> expected [1,2,3], was [{string.Join(", ", callbacks)}]");
    }

    static void DecorateWithRawDecoratorWorks()
    {
        var leftTicket = new ScriptTicket("left");

        var decoratorBuilder = new TentacleServiceDecoratorBuilder()
            .DecorateScriptServiceV2With(new ScriptServiceV2DecoratorBuilder()
                .DecorateStartScriptWith((service, command, options) => service.StartScriptAsync(new StartScriptCommandV2(command.ScriptBody, command.Isolation, command.ScriptIsolationMutexTimeout, command.IsolationMutexName, command.Arguments, command.TaskId, leftTicket, command.DurationToWaitForScriptToFinish), options))
                .Build());

        var decoratedService = decoratorBuilder.Build().Decorate(new FakeScriptServiceV2());

        var response = decoratedService.StartScriptAsync(BuildStartScriptCommand(), new HalibutProxyRequestOptions(CancellationToken.None)).GetAwaiter().GetResult();

        Check(response.Ticket == leftTicket,
            $"DecorateWithRawDecoratorWorks -> expected ticket to be rewritten, was {response.Ticket}");
    }

    static void CombiningTentacleServiceDecoratorFactoryAppliesFirstFactoryOutermost()
    {
        var order = new List<string>();

        var first = new RecordingDecoratorFactory("first", order);
        var second = new RecordingDecoratorFactory("second", order);

        var combined = new CombiningTentacleServiceDecoratorFactory(first, second);
        combined.Decorate(new FakeScriptServiceV2());

        // first factory is outermost, which means its Decorate is invoked last on the way back out,
        // wrapping everything built by the factories pointed at the original service.
        Check(order.Count == 2 && order[0] == "second" && order[1] == "first",
            $"CombiningTentacleServiceDecoratorFactoryAppliesFirstFactoryOutermost -> expected [second, first], was [{string.Join(", ", order)}]");
    }

    static void CallThroughDefaultsArePreserved()
    {
        var builder = new ScriptServiceV2DecoratorBuilder()
            .BeforeCompleteScript(() => Task.CompletedTask);

        // 'Build' without any method decoration must still call through to the inner service
        var untouched = builder.Build().Decorate(new FakeScriptServiceV2());

        var response = untouched.StartScriptAsync(BuildStartScriptCommand(), new HalibutProxyRequestOptions(CancellationToken.None)).GetAwaiter().GetResult();

        Check(response.Ticket == FakeScriptServiceV2.Ticket,
            $"CallThroughDefaultsArePreserved -> expected ticket to match fake service ticket, was {response.Ticket}");
    }

    static void Check(bool condition, string failureMessage)
    {
        if (condition)
        {
            Console.WriteLine("PASS");
            return;
        }

        Console.WriteLine($"FAIL {failureMessage}");
        failures++;
    }

    static StartScriptCommandV2 BuildStartScriptCommand()
        => new(
            "echo hello",
            ScriptIsolationLevel.NoIsolation,
            TimeSpan.Zero,
            null,
            Array.Empty<string>(),
            "TaskId",
            new ScriptTicket("TicketId"),
            TimeSpan.FromSeconds(5));

    class FakeScriptServiceV2 : IAsyncClientScriptServiceV2
    {
        public static readonly ScriptTicket Ticket = new("fake-ticket");

        public Task<ScriptStatusResponseV2> StartScriptAsync(StartScriptCommandV2 command, HalibutProxyRequestOptions proxyRequestOptions)
        {
            var inner = command.ScriptTicket ?? Ticket;
            return Task.FromResult(new ScriptStatusResponseV2(inner, ProcessState.Complete, 0, new List<ProcessOutput>(), 0));
        }

        public Task<ScriptStatusResponseV2> GetStatusAsync(ScriptStatusRequestV2 request, HalibutProxyRequestOptions proxyRequestOptions)
            => Task.FromResult(new ScriptStatusResponseV2(request.ScriptTicket, ProcessState.Complete, 0, new List<ProcessOutput>(), 0));

        public Task<ScriptStatusResponseV2> CancelScriptAsync(CancelScriptCommandV2 command, HalibutProxyRequestOptions proxyRequestOptions)
            => Task.FromResult(new ScriptStatusResponseV2(command.ScriptTicket, ProcessState.Complete, 0, new List<ProcessOutput>(), 0));

        public Task CompleteScriptAsync(CompleteScriptCommandV2 command, HalibutProxyRequestOptions proxyRequestOptions)
            => Task.CompletedTask;
    }

    class RecordingDecoratorFactory : ITentacleServiceDecoratorFactory
    {
        readonly string name;
        readonly List<string> order;

        public RecordingDecoratorFactory(string name, List<string> order)
        {
            this.name = name;
            this.order = order;
        }

        public IAsyncClientScriptService Decorate(IAsyncClientScriptService scriptService)
        {
            order.Add(name);
            return scriptService;
        }

        public IAsyncClientScriptServiceV2 Decorate(IAsyncClientScriptServiceV2 scriptService)
        {
            order.Add(name);
            return scriptService;
        }

        public IAsyncClientFileTransferService Decorate(IAsyncClientFileTransferService service)
        {
            order.Add(name);
            return service;
        }

        public IAsyncClientCapabilitiesServiceV2 Decorate(IAsyncClientCapabilitiesServiceV2 service)
        {
            order.Add(name);
            return service;
        }

        public IAsyncClientScriptServiceV3Alpha Decorate(IAsyncClientScriptServiceV3Alpha service)
        {
            order.Add(name);
            return service;
        }
    }
}

