namespace FluentAssertions
{
    public static class AssertionStubExtensions
    {
        public static GenericCollectionAssertions<T> Should<T>(this IEnumerable<T> collection) => new GenericCollectionAssertions<T>(collection);

        public static NumericAssertions Should(this long value) => new NumericAssertions(value);

        public static AsyncFunctionAssertions Should(this Func<Task> action) => new AsyncFunctionAssertions(action);
    }

    public class GenericCollectionAssertions<T>
    {
        readonly IEnumerable<T> subject;

        public GenericCollectionAssertions(IEnumerable<T> subject)
        {
            this.subject = subject;
        }

        public void Equal(params T[] elements)
        {
            var matches = elements.SequenceEqual(subject);
            if (!matches)
            {
                throw new Exception($"Expected [{string.Join(",", elements)}] but was [{string.Join(",", subject)}]");
            }
        }
    }

    public class NumericAssertions
    {
        readonly long value;

        public NumericAssertions(long value)
        {
            this.value = value;
        }

        public void Be(object expected)
        {
            if (!Equals(value, Convert.ToInt64(expected)))
            {
                throw new Exception($"Expected {expected} but was {value}");
            }
        }
    }

    public class AsyncFunctionAssertions
    {
        readonly Func<Task> action;

        public AsyncFunctionAssertions(Func<Task> action)
        {
            this.action = action;
        }

        public async Task<ExceptionAssertions<TException>> ThrowAsync<TException>() where TException : Exception
        {
            try
            {
                await action();
            }
            catch (TException e)
            {
                return new ExceptionAssertions<TException>(e);
            }

            throw new Exception($"Expected {typeof(TException).Name} to be thrown but no exception was thrown");
        }
    }

    public class ExceptionAssertions<TException> where TException : Exception
    {
        readonly TException exception;

        public ExceptionAssertions(TException exception)
        {
            this.exception = exception;
        }

        public ExceptionAssertions<TException> WithMessage(string expectedMessage)
        {
            if (!string.Equals(expectedMessage, exception.Message, StringComparison.Ordinal))
            {
                throw new Exception($"Expected exception message '{expectedMessage}' but was '{exception.Message}'");
            }

            return this;
        }
    }
}

