    }

    static void ProxyDecoratorRunsBeforePerServiceDecorator()
    {
        // A proxy-based decorator (recording usages) must run before the per-service 'Boom' hook.
        var usages = new MethodUsages();

        var callOrder = new List<string>();

        var decoratorBuilder = new TentacleServiceDecoratorBuilder()
            .RegisterProxyDecorator<IAsyncClientScriptServiceV2>(service => new RecordingScriptServiceV2(service, usages, callOrder))
            .DecorateScriptServiceV2With(builder => builder
                .BeforeStartScript(async () => throw new Exception("Boom")));

        var decoratedService = decoratorBuilder.Build().Decorate(new FakeScriptServiceV2());

        var threwBoom = false;
        try
        {
            decoratedService.StartScriptAsync(BuildStartScriptCommand(), new HalibutProxyRequestOptions(CancellationToken.None)).GetAwaiter().GetResult();
