        {
            this.inner = inner;
            this.usages = usages;
            this.callOrder = callOrder;
        }

        public async Task<ScriptStatusResponseV2> StartScriptAsync(StartScriptCommandV2 command, HalibutProxyRequestOptions proxyRequestOptions)
        {
            callOrder.Add("proxy");
            usages.RecordCallStart(System.Reflection.MethodBase.GetCurrentMethod()!);
            try
            {
                return await inner.StartScriptAsync(command, proxyRequestOptions);
