using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Text.RegularExpressions;
using System.Text.Json;
using System.Threading;
using System.Threading.Tasks;
using k8s.Models;
using Octopus.Diagnostics;
using Octopus.Tentacle.Contracts;
using Octopus.Tentacle.Contracts.ScriptServiceV3Alpha;
using Octopus.Tentacle.Kubernetes;
using Octopus.Tentacle.Kubernetes.Scripts;
using Octopus.Tentacle.Scripts;

internal static class KubernetesCheckMain
{
    static int failures;

    static int Main(string[] args)
    {
        try
        {
            CheckImagePullSecretName();
            CheckDockerConfigJson();
            CheckCreateImagePullSecretFlows();
        }
        catch (Exception e)
        {
            Console.WriteLine("HARNESS EXCEPTION: " + e);
            failures++;
        }

        Console.WriteLine(failures == 0 ? "ALL CHECKS PASSED" : $"{failures} CHECKS FAILED");
        return failures == 0 ? 0 : 1;
    }

    static void CheckImagePullSecretName()
    {
        var m = typeof(RunningKubernetesJob).GetMethod("BuildImagePullSecretName", BindingFlags.NonPublic | BindingFlags.Static);
        Check(m != null, "BuildImagePullSecretName should exist");
        var n1 = (string)m!.Invoke(null, new object[] { "https://reg.example.com", "bob" })!;
        var n2 = (string)m.Invoke(null, new object[] { "https://reg.example.com", "bob" })!;
        var n3 = (string)m.Invoke(null, new object[] { "https://reg.example.com", "alice" })!;
        Check(n1 == n2, $"name must be deterministic: '{n1}' vs '{n2}'");
        Check(n1 != n3, $"name must vary by username: '{n1}' vs '{n3}'");
        Check(Regex.IsMatch(n1, @"^octopus-image-pull-secret-[0-9a-f]{16}$"), $"name format unexpected: '{n1}'");
        Check(n1.Length == "octopus-image-pull-secret-".Length + 16, $"name length unexpected: {n1.Length}");
        Console.WriteLine("OK: BuildImagePullSecretName -> " + n1);
    }

    static void CheckDockerConfigJson()
    {
        var m = typeof(RunningKubernetesJob).GetMethod("CreateDockerConfigJson", BindingFlags.NonPublic | BindingFlags.Static);
        Check(m != null, "CreateDockerConfigJson should exist");

        var ctx = new KubernetesJobScriptExecutionContext("my-image:1.0", "https://reg.example.com", "bob", "secret!pass");
        var bytes = (byte[])m!.Invoke(null, new object[] { ctx })!;
        using var doc = JsonDocument.Parse(bytes);
        var auths = doc.RootElement.GetProperty("auths");
        var registry = auths.GetProperty("https://reg.example.com");
        Check(registry.GetProperty("username").GetString() == "bob", "username mismatch in docker config");
        Check(registry.GetProperty("password").GetString() == "secret!pass", "password mismatch in docker config");
        var expectedAuth = Convert.ToBase64String(System.Text.Encoding.UTF8.GetBytes("bob:secret!pass"));
        Check(registry.GetProperty("auth").GetString() == expectedAuth, $"auth mismatch in docker config: {registry.GetProperty("auth").GetString()} vs {expectedAuth}");

        // null properties should still serialize
        var emptyCtx = new KubernetesJobScriptExecutionContext(null, "https://reg2.example.com", "carol", null);
        var emptyDoc = (byte[])m.Invoke(null, new object[] { emptyCtx })!;
        using var doc2 = JsonDocument.Parse(emptyDoc);
        Check(doc2.RootElement.GetProperty("auths").GetProperty("https://reg2.example.com").GetProperty("auth").GetString() == Convert.ToBase64String(System.Text.Encoding.UTF8.GetBytes("carol:")), "auth with null password unexpected");
        Console.WriteLine("OK: CreateDockerConfigJson round-trips");
    }

    static void CheckCreateImagePullSecretFlows()
    {
        var noCreds = new KubernetesJobScriptExecutionContext("image", null, null, null);
        var recorder = new RecordingSecretService();
        var job = BuildJob(noCreds, recorder);
        var name = InvokeCreateImagePullSecret(job, CancellationToken.None);
        Check(name == null, "no credentials should return null name");
        Check(recorder.Calls.Count == 0, $"no credentials should not touch the secret service, got {string.Join(",", recorder.Calls)}");

        var withCreds = new KubernetesJobScriptExecutionContext("image", "https://reg.example.com", "bob", "pw");
        recorder = new RecordingSecretService();
        job = BuildJob(withCreds, recorder);
        var expectedName = (string)typeof(RunningKubernetesJob)
            .GetMethod("BuildImagePullSecretName", BindingFlags.NonPublic | BindingFlags.Static)!
            .Invoke(null, new object[] { "https://reg.example.com", "bob" })!;
        name = InvokeCreateImagePullSecret(job, CancellationToken.None);
        Check(name == expectedName, $"returned name should match deterministic name: '{name}' vs '{expectedName}'");
        Check(recorder.Calls.Count == 2 && recorder.Calls[0] == "TryGet" && recorder.Calls[1] == "Create", $"expected TryGet then Create, got {string.Join(",", recorder.Calls)}");
        Check(recorder.Created?.Metadata?.Name == name, "created secret name mismatch");
        Check(recorder.Created?.Type == "kubernetes.io/dockerconfigjson", "created secret type mismatch");
        Check(recorder.Created?.Data?.ContainsKey(".dockerconfigjson") == true, "created secret missing .dockerconfigjson data key");
        Check(recorder.Created?.ApiVersion == "v1" && recorder.Created?.Kind == "Secret", "created secret apiVersion/kind mismatch");

        recorder = new RecordingSecretService { Existing = new V1Secret() };
        job = BuildJob(withCreds, recorder);
        name = InvokeCreateImagePullSecret(job, CancellationToken.None);
        Check(recorder.Calls.Count == 2 && recorder.Calls[0] == "TryGet" && recorder.Calls[1] == "Update", $"expected TryGet then Update, got {string.Join(",", recorder.Calls)}");
        Check(recorder.UpdatedName == name, "updated secret name mismatch");
        Check(recorder.UpdatedData?.ContainsKey(".dockerconfigjson") == true, "updated data missing .dockerconfigjson key");
        Console.WriteLine("OK: CreateImagePullSecret flows (null / create / update)");
    }

    static string? InvokeCreateImagePullSecret(RunningKubernetesJob job, CancellationToken ct)
    {
        var m = typeof(RunningKubernetesJob).GetMethod("CreateImagePullSecret", BindingFlags.NonPublic | BindingFlags.Instance)!;
        var task = (Task<string?>)m.Invoke(job, new object?[] { ct })!;
        return task.GetAwaiter().GetResult();
    }

    static RunningKubernetesJob BuildJob(KubernetesJobScriptExecutionContext ctx, IKubernetesSecretService secretService)
    {
        return new RunningKubernetesJob(
            new FakeWorkspace(),
            new FakeScriptLog(),
            new ScriptTicket("Ticket-1"),
            "task-1",
            new FakeLog(),
            new FakeStateStore(),
            new FakeJobService(),
            new FakeContainerResolver(),
            new FakeInstanceSelector(),
            secretService,
            ctx,
            CancellationToken.None);
    }

    static void Check(bool condition, string message)
    {
        if (!condition)
        {
            Console.WriteLine("FAIL: " + message);
            failures++;
        }
    }

    class FakeWorkspace : IScriptWorkspace
    {
        public string[]? ScriptArguments { get; set; }
        public ScriptIsolationLevel IsolationLevel { get; set; }
        public TimeSpan ScriptMutexAcquireTimeout { get; set; } = TimeSpan.FromSeconds(10);
        public string? ScriptMutexName { get; set; }
        public string BootstrapScriptFilePath => "/octopus/Work/Ticket-1/bootstrap.sh";
        public void WriteFile(string filename, string contents)
        {
        }

        public IScriptLog CreateLog() => new FakeScriptLog();
        public Stream OpenFileStreamForReading(string filename) => throw new FileNotFoundException(filename);
    }

    class FakeScriptLog : IScriptLog
    {
        public IScriptLogWriter CreateWriter() => new FakeWriter();
    }

    class FakeWriter : IScriptLogWriter
    {
        public void Dispose()
        {
        }

        public void WriteOutput(ProcessOutputSource source, string message)
        {
